test('pack-access receipt values cannot carry arbitrary private payloads into public packets',async()=>{for(const level of [{canary:'PRIVATE-PACK-ACCESS-CANARY'},'PRIVATE-LEVEL',null,1]){const p=observedPlan();p.checkpoint.operations.push({kind:'pack-access',level});assert.ok(errors(p).length);await assert.rejects(packet(p));const config=await packet(observedPlan());config.controlReceipts.push({kind:'pack-access',level});assert.ok(publicAdmittedPacketErrors(config).length);}for(const level of ['NONE','OBSERVER']){const p=observedPlan();p.checkpoint.mutations.push({kind:'pack-configuration',uuid:p.checkpoint.resources.find(r=>r.kind==='Pack').uuid,userId:C.pin.gm,batch:p.batch,role:'PLAYER',level});p.checkpoint.operations.push({kind:'pack-access',level});assert.deepEqual(errors(p),[]);assert.deepEqual(publicAdmittedPacketErrors(await packet(p)),[]);}});
function optionsFor(p,user=C.pin.gm,phase=p.checkpoint.phase,suffix='0'){return {packetId:'packet-'+suffix,segmentId:'segment-'+suffix,userId:user,phase,bootstrapMacroUuid:p.checkpoint.resources.find(r=>r.kind==='Macro')?.uuid??resources(p.batch,p.mode).find(r=>r.kind==='Macro').uuid};}
function packet(p,user=C.pin.gm,phase=p.checkpoint.phase){return admittedControllerInputs(p,optionsFor(p,user,phase));}
function activeEmpty(mode='synthetic'){const p=observedPlan(mode);p.checkpoint=copy(pending().checkpoint);const backup={kind:'backup-manifest',batch:p.batch,source:p.mode,value:{synthetic:true}};p.baseline.backupManifestSha256=sha(JSON.stringify(backup));return p;}
function localSegment(issued){const p=issued.packet;return {packetId:p.anchor.packetId,segmentId:p.anchor.segmentId,parentRevision:p.anchor.revision,parentCheckpointSha256:p.anchor.checkpointSha256,packetSha256:sha(issued.packetBytes),identity:identityFor(p.audience.userId),runtime:p.runtime.map(r=>({...r,served:r.packaged})),navigation:{timeOrigin:1000,type:'navigate'},events:[],mutations:[],captures:[],controlState:{phase:p.phase,resources:copy(p.resources),mappings:copy(p.mappings),packMappings:copy(p.packMappings)},firstFailure:null};}
function event(s,kind,value){const sequence=s.events.length;if(kind==='operation')s.events.push({sequence,kind,value:copy(value)});else{const array=kind==='mutation'?s.mutations:s.captures,index=array.length;array.push(copy(value));s.events.push({sequence,kind,index});}}
async function setupChain(mode='synthetic'){const p=activeEmpty(mode),issued=await issue(p,optionsFor(p)),s=localSegment(issued),full=observedPlan(mode).checkpoint;s.controlState={phase:'gm',resources:copy(full.resources),mappings:copy(full.mappings),packMappings:copy(full.packMappings)};const remaining=[...full.resources],known=new Set();while(remaining.length){const n=remaining.findIndex(r=>!r.parentUuid||known.has(r.parentUuid));assert.ok(n>=0);const r=remaining.splice(n,1)[0];event(s,'mutation',full.mutations.find(m=>m.kind==='create'&&m.uuid===r.uuid));known.add(r.uuid);}event(s,'operation',full.operations[0]);for(const m of full.mutations.filter(m=>m.kind!=='create'))event(s,'mutation',m);event(s,'operation',full.operations[1]);assert.deepEqual(admittedControllerSegmentErrors(s,issued.packet),[]);return {issued,segment:s,plan:await merge(issued.plan,s)};}
async function captureSegment(plan,caseId,suffix){const user=caseId.startsWith('gm-')?C.pin.gm:C.pin.player,issued=await issue(plan,optionsFor(plan,user,caseId.includes('reload')?'reload':user===C.pin.gm?'gm':'player',suffix)),s=localSegment(issued),c=await capture(plan,caseId);s.navigation=copy(c.navigation);event(s,'operation',{kind:'resume',userId:user,navigation:copy(s.navigation)});event(s,'operation',{kind:'begin',caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'capture',c);return {issued,segment:s,plan:await merge(issued.plan,s)};}

function appendFabricatedHistory(issued,s){const p=copy(issued.plan),segmentBytes=JSON.stringify(s);p.checkpoint.phase=s.controlState.phase;p.checkpoint.resources=copy(s.controlState.resources);p.checkpoint.mappings=copy(s.controlState.mappings);p.checkpoint.packMappings=copy(s.controlState.packMappings);for(const e of s.events){if(e.kind==='operation')p.checkpoint.operations.push(copy(e.value));else if(e.kind==='mutation')p.checkpoint.mutations.push(copy(s.mutations[e.index]));else if(e.kind==='capture')p.checkpoint.captures.push(copy(s.captures[e.index]));}p.checkpoint.failure??=copy(s.firstFailure);p.handoff.acceptedSegments.push({segmentId:s.segmentId,segmentSha256:sha(segmentBytes),segmentBytes,packetBytes:issued.packetBytes,packetSha256:sha(issued.packetBytes),segment:copy(s),packet:copy(issued.packet)});p.handoff.revision++;p.handoff.issued=null;return p;}
function beginEvent(s,c){event(s,'operation',{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});}
async function lifecycleCounterexample(kind){const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','lifecycle-'+kind)),s=localSegment(issued),a=await capture(plan),b=await capture(plan,'gm-owned-repeats-membership');beginEvent(s,a);if(kind==='overlap'){beginEvent(s,b);event(s,'capture',a);event(s,'capture',b);}return {issued,segment:s,forged:appendFabricatedHistory(issued,s)};}
for(const kind of ['overlap','unfinished']){
    test('lifecycle '+kind+' segment is rejected',async()=>{const {issued,segment}=await lifecycleCounterexample(kind);assert.ok(admittedControllerSegmentErrors(segment,issued.packet).some(e=>e.includes('lifecycle')));});
    test('lifecycle '+kind+' private merge is rejected',async()=>{const {issued,segment}=await lifecycleCounterexample(kind);await assert.rejects(merge(issued.plan,segment),/lifecycle/);});
    test('lifecycle '+kind+' fabricated accepted history fails replay',async()=>{const {forged}=await lifecycleCounterexample(kind);const result=await replayAdmittedControllerHistory(forged);assert.equal(result.status,'failed');assert.ok(result.errors.some(e=>e.includes('lifecycle')));});
    test('lifecycle '+kind+' identical retry cannot grandfather the defect',async()=>{const {forged,segment}=await lifecycleCounterexample(kind);await assert.rejects(merge(forged,segment),/lifecycle/);});
}

function memoryStorage(backing=new Map()){return {getItem:key=>backing.get(key)??null,setItem:(key,value)=>backing.set(key,String(value)),removeItem:key=>backing.delete(key),backing};}
