    const h={plan,issued,storage,selected:'gm-trainer-core-to-optional',launches:[],errors:[],deletions:[],verifications:[],output:'',getDataFailure:false,closeFailure:false,resolveFailure:false,packConfiguration:{...copy(plan.baseline.packConfiguration),[C.fixtures.pack]:{ownership:{PLAYER:'NONE',TRUSTED:'NONE',ASSISTANT:'NONE'}}}};
