    const html={find:selector=>({val:value=>{if(value!==undefined)h.output=value;return selector==='[data-p05-case]'?h.selected:h.output;},on:(_name,handler)=>{h.handler=handler;}})};
    h.launch=()=>{const root={isConnected:true,textContent:'Synthetic view',outerHTML:'<div>Synthetic view</div>',querySelector:()=>({scrollTop:0,scrollHeight:200,clientHeight:100}),addEventListener:()=>{}},review={rendered:true,element:[root],getData:()=>{if(h.getDataFailure)throw Error('Synthetic getData failure');return copy(views[h.selected]??views['gm-trainer-core-to-optional']);},close:()=>{if(h.closeFailure)return Promise.reject(Error('Synthetic close failure'));review.closePromise??=Promise.resolve().then(()=>{review.rendered=false;root.isConnected=false;});return review.closePromise;}};h.launches.push(review);return {status:'review-requested',review,issues:[]};};
