test('lifecycle service double refuses concurrent begin actions before async resolution',()=>withLifecycleController(async h=>{await Promise.all([h.click('begin','gm-trainer-core-to-optional'),h.click('begin','gm-owned-repeats-membership')]);assert.equal(h.launches.length,1);}));
test('lifecycle service double refuses silent cleanup of a healthy unfinished review',()=>withLifecycleController(async h=>{await h.click('begin');await h.click('cleanup');assert.equal(h.deletions.length,0);await assert.rejects(h.controller.exportSegment(),/current review|pending|unfinished/);}));
test('lifecycle service double records failed review abort before owned cleanup',()=>withLifecycleController(async h=>{h.getDataFailure=true;await h.click('begin');h.getDataFailure=false;await h.click('cleanup');const s=await h.controller.exportSegment();assert.equal(s.captures.length,0);assert.ok(s.events.some(e=>e.kind==='operation'&&e.value.kind==='review-abort'));assert.ok(s.firstFailure);assert.deepEqual(admittedControllerSegmentErrors(s,h.issued.packet),[]);}));
test('lifecycle service double refuses reopening the same packet with an unfinished review',()=>withLifecycleController(async h=>{await h.click('begin');await assert.rejects(h.open(),/lifecycle|unfinished|unexported/);}));
test('lifecycle service double refuses a healthy abort without making recovery necessary',()=>withLifecycleController(async h=>{await h.click('begin');await h.click('abort-review');await h.click('finish');const s=await h.controller.exportSegment();assert.equal(s.captures.length,1);assert.equal(s.firstFailure,null);}));
test('lifecycle refresh rejects an unfinished exported segment even when the pending flag is false',async()=>{const {plan}=await setupChain('native'),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','refresh-unfinished')),s=localSegment(issued);beginEvent(s,await capture(plan));const closed=await merge(issued.plan,localSegment(issued)),next=await issue(closed,optionsFor(closed,C.pin.gm,'gm','refresh-next')),bytes=JSON.stringify(s);await assert.rejects(refreshFeatureReviewPacket({packet:issued.packet,next:next.packet,exported:{segment:s,bytes,sha256:sha(bytes),eventCount:s.events.length},localEventCount:s.events.length,pendingReview:false,identity:identityFor(C.pin.gm),verifyExecution:()=>{},packetSha256:sha(next.packetBytes)},[]),/lifecycle/);});
