function failedEvent(s,caseId,operation='finish'){const failure={operation,caseId,reason:'Synthetic genuine review failure'};event(s,'operation',{kind:'failure',...failure});s.firstFailure??=copy(failure);}
function abortEvent(s,c,beginRecorded=true){event(s,'operation',{kind:'review-abort',caseId:c.caseId,beginRecorded,reason:'Synthetic failed pending review closed; no capture'});}
async function assertLifecycleRejected(issued,s){assert.ok(admittedControllerSegmentErrors(s,issued.packet).some(e=>e.includes('lifecycle')));await assert.rejects(merge(issued.plan,s),/lifecycle/);const forged=appendFabricatedHistory(issued,s);assert.equal((await replayAdmittedControllerHistory(forged)).status,'failed');await assert.rejects(merge(forged,s));}
const invalidLifecycle={
    'repeated active begin':(s,a)=>{beginEvent(s,a);beginEvent(s,a);event(s,'capture',a);},
    'completed local begin':(s,a)=>{reviewEvents(s,a);beginEvent(s,a);},
    'orphan capture':(s,a)=>event(s,'capture',a),
    'mismatched case capture':(s,a,b)=>{beginEvent(s,a);event(s,'capture',b);},
    'mismatched summary outcome':(s,a)=>{beginEvent(s,a);a.summary.launchStatus='not-opened';event(s,'capture',a);},
    'mismatched body resolution':(s,a)=>{beginEvent(s,a);a.summary.bodyExecuted=false;a.summary.resolutionDenied=true;a.summary.launchStatus='not-opened';a.view=null;a.resolution.error='Synthetic denial';event(s,'capture',a);},
    'reordered captures':(s,a,b)=>{beginEvent(s,a);event(s,'capture',b);beginEvent(s,b);event(s,'capture',a);},
    'duplicate capture':(s,a)=>{reviewEvents(s,a);event(s,'capture',a);},
    'failure leaves review pending':(s,a)=>{beginEvent(s,a);failedEvent(s,a.caseId);},
    'orphan recorded abort':(s,a)=>{failedEvent(s,a.caseId);abortEvent(s,a);},
    'abort without failure':(s,a)=>{beginEvent(s,a);abortEvent(s,a);},
    'wrong pending abort':(s,a,b)=>{beginEvent(s,a);failedEvent(s,a.caseId);abortEvent(s,b);},
    'capture after abort':(s,a)=>{beginEvent(s,a);failedEvent(s,a.caseId);abortEvent(s,a);event(s,'capture',a);},
    'duplicate abort':(s,a)=>{beginEvent(s,a);failedEvent(s,a.caseId);abortEvent(s,a);abortEvent(s,a);},
    'unrecorded abort lacks opening failure':(s,a)=>{failedEvent(s,a.caseId,'finish');abortEvent(s,a,false);},
    'checkpoint before failed abort':(s,a)=>{beginEvent(s,a);event(s,'operation',{kind:'checkpoint',snapshot:{synthetic:true}});failedEvent(s,a.caseId);abortEvent(s,a);}
};
for(const [name,make]of Object.entries(invalidLifecycle))test('lifecycle rejects '+name+' across validation merge replay and retry',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','invalid-lifecycle')),s=localSegment(issued);make(s,await capture(plan),await capture(plan,'gm-owned-repeats-membership'));await assertLifecycleRejected(issued,s);});
test('lifecycle rejects begin for a packet-completed case',async()=>{let {plan}=await setupChain();plan=(await captureSegment(plan,'gm-trainer-core-to-optional','packet-complete')).plan;const issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','repeat-completed')),s=localSegment(issued);beginEvent(s,await capture(plan));await assertLifecycleRejected(issued,s);});
