test('lifecycle honest captured failure remains closed and sticky',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','failed-capture')),s=localSegment(issued),c=await capture(plan);c.summary.checks.push({name:'Synthetic failed observation',passed:false});reviewEvents(s,c);failedEvent(s,c.caseId);const merged=await merge(issued.plan,s);assert.equal(merged.checkpoint.captures.length,1);assert.deepEqual(merged.checkpoint.failure,s.firstFailure);assert.equal((await replayAdmittedControllerHistory(merged)).status,'passed');assert.equal((await packet(merged)).resume.stopLatched,true);});
