test('lifecycle failed opening abort has no invented begin or capture',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','opening-abort')),s=localSegment(issued),c=await capture(plan);failedEvent(s,c.caseId,'begin');abortEvent(s,c,false);const merged=await merge(issued.plan,s);assert.equal(merged.checkpoint.captures.length,0);assert.equal(merged.checkpoint.operations.filter(o=>o.kind==='begin').length,0);assert.equal((await replayAdmittedControllerHistory(merged)).status,'passed');});
test('lifecycle incomplete private evidence remains inspectable but cannot become a handoff',()=>temp(async dir=>{const p=observedPlan(),s={events:[],mutations:[],captures:[],firstFailure:null};beginEvent(s,await capture(p));p.checkpoint.operations.push(s.events[0].value);p.evidence.status='incomplete';await rawProofs(dir,p);const result=await check(p,{rawDirectory:dir});assert.equal(result.integrity,'passed',result.errors.join('; '));assert.ok(result.findings.some(e=>e.includes('lifecycle')));assert.equal(result.evidenceComplete,false);assert.equal(result.nativeAccepted,false);await assert.rejects(packet(p),/lifecycle/);}));

