test('lifecycle service failed finish can explicitly abort without inventing a capture',()=>withLifecycleController(async h=>{await h.click('begin');h.snapshotFailure=true;await h.click('finish');h.snapshotFailure=false;await h.click('abort-review');const s=await h.controller.exportSegment();assert.equal(s.captures.length,0);assert.equal(s.firstFailure.operation,'finish');assert.equal(h.deletions.length,0);assert.equal((await replayAdmittedControllerHistory(await merge(h.issued.plan,s))).status,'passed');}));
test('lifecycle service uncertain close retains pending evidence and first failure',()=>withLifecycleController(async h=>{h.getDataFailure=true;await h.click('begin');h.getDataFailure=false;const first=copy(JSON.parse(h.output).localSegment.firstFailure);h.closeFailure=true;await h.click('cleanup');assert.equal(h.deletions.length,0);const blocked=JSON.parse(h.output);assert.equal(blocked.status,'blocked-pending-review');assert.equal(blocked.pending.beginRecorded,true);assert.deepEqual(blocked.localSegment.firstFailure,first);assert.equal(blocked.localSegment.events.filter(e=>e.kind==='operation'&&e.value.kind==='review-abort').length,0);await assert.rejects(h.controller.exportSegment(),/current review/);h.closeFailure=false;await h.click('abort-review');const s=await h.controller.exportSegment();assert.equal(s.captures.length,0);assert.deepEqual(s.firstFailure,first);assert.equal((await replayAdmittedControllerHistory(await merge(h.issued.plan,s))).status,'passed');}));
test('lifecycle service export serializes against begin and repeated export stays byte-identical',()=>withLifecycleController(async h=>{const [s]=await Promise.all([h.controller.exportSegment(),h.click('begin')]);assert.equal(h.launches.length,0);const bytes=h.output;await h.click('checkpoint');await h.click('begin');assert.equal(h.output,bytes);assert.deepEqual(await h.controller.exportSegment(),s);for(const raw of h.storage.backing.values()){const m=JSON.parse(raw);assert.equal(m.status,'sealed');assert.equal(m.segmentSha256,sha(bytes));assert.ok(Object.values(m).every(v=>v===null||['string','number'].includes(typeof v)));assert.doesNotMatch(raw,/captures|snapshot|protectedDocuments|settings|beforeSha256/);}assert.equal((await replayAdmittedControllerHistory(await merge(h.issued.plan,s))).status,'passed');}));
test('lifecycle service acknowledged refresh starts a local-only next segment',()=>withLifecycleController(async h=>{await h.click('begin');await h.click('finish');const first=await h.controller.exportSegment(),merged=await merge(h.issued.plan,first),next=await issue(merged,optionsFor(merged,C.pin.gm,'gm','service-refreshed'));await h.controller.useCheckpoint(next.packet,{packetBytes:next.packetBytes});await h.click('begin','gm-owned-repeats-membership');await h.click('finish');const second=await h.controller.exportSegment();assert.deepEqual(second.captures.map(c=>c.caseId),['gm-owned-repeats-membership']);assert.doesNotMatch(JSON.stringify(second),/gm-trainer-core-to-optional/);assert.ok(h.verifications.some(v=>v.operation==='verify-private-segment-ack'&&v.precedingSegmentId===first.segmentId));const final=await merge(next.plan,second);assert.equal(final.checkpoint.captures.length,2);assert.equal((await replayAdmittedControllerHistory(final)).status,'passed');}));
test('lifecycle service sealed reload requires a newer acknowledged packet and preserves private history',()=>withLifecycleController(async h=>{await h.click('begin');await h.click('finish');const first=await h.controller.exportSegment(),old=h.controller,merged=await merge(h.issued.plan,first),next=await issue(merged,optionsFor(merged,C.pin.gm,'reload','service-reloaded'));await assert.rejects(h.open(),/sealed segment/);h.controller=await h.open(next.packet,next.packetBytes);await assert.rejects(old.exportSegment(),/ownership changed/);const local=await h.controller.exportSegment();assert.equal(local.captures.length,0);assert.equal(local.events[0].value.kind,'resume');assert.ok(h.verifications.some(v=>v.operation==='verify-private-segment-ack'&&v.precedingSegmentId===first.segmentId));const final=await merge(next.plan,local);assert.equal(final.checkpoint.captures.length,1);assert.equal((await replayAdmittedControllerHistory(final)).status,'passed');}));
test('lifecycle service dirty reload cannot bypass the hold with different packet IDs',()=>withLifecycleController(async h=>{await h.click('begin');const p=copy(h.issued.packet);p.anchor.packetId='different-packet';p.anchor.segmentId='different-segment';p.anchor.revision++;await assert.rejects(h.open(p),/unfinished\/unexported/);assert.equal(h.launches.length,1);await assert.rejects(h.controller.exportSegment(),/current review/);}));
