test('lifecycle player failed abort stays local and hands only sticky failure to GM cleanup',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.player,'player','player-abort')),s=localSegment(issued),c=await capture(plan,'player-trainer-review');beginEvent(s,c);failedEvent(s,c.caseId);abortEvent(s,c);const merged=await merge(issued.plan,s),next=await issue(merged,optionsFor(merged,C.pin.gm,'cleanup','cleanup-player-failure'));assert.equal(s.mutations.length,0);assert.equal(merged.checkpoint.captures.length,0);assert.equal(next.packet.resume.stopLatched,true);assert.equal(next.packet.resume.firstFailureRef,sha(s.firstFailure));assert.equal((await replayAdmittedControllerHistory(merged)).status,'passed');});
test('lifecycle refresh refuses altered or missing exact export bytes before acknowledgement',async()=>{const {plan}=await setupChain('native'),first=await captureSegment(plan,'player-trainer-review','bytes-first'),next=await issue(first.plan,optionsFor(first.plan,C.pin.player,'player','bytes-next')),bytes=JSON.stringify(first.segment);let acknowledgements=0;const base={packet:first.issued.packet,next:next.packet,exported:{segment:first.segment,bytes,sha256:sha(bytes),eventCount:first.segment.events.length},localEventCount:first.segment.events.length,pendingReview:false,identity:identityFor(C.pin.player),verifyExecution:()=>{acknowledgements++;},packetSha256:sha(next.packetBytes)};for(const mutate of [e=>delete e.bytes,e=>e.bytes=' '+e.bytes,e=>e.sha256='b'.repeat(64)]){const args={...base,exported:copy(base.exported)};mutate(args.exported);await assert.rejects(refreshFeatureReviewPacket(args,[]),/byte binding/);}assert.equal(acknowledgements,0);});
test('lifecycle service close serializes against an acknowledged refresh',()=>withLifecycleController(async h=>{const s=await h.controller.exportSegment(),merged=await merge(h.issued.plan,s),next=await issue(merged,optionsFor(merged,C.pin.gm,'gm','close-refresh'));const results=await Promise.allSettled([h.controller.close(),h.controller.useCheckpoint(next.packet,{packetBytes:next.packetBytes})]);assert.equal(results[0].status,'fulfilled');assert.equal(results[1].status,'rejected');assert.match(String(results[1].reason),/lifecycle/);const marker=JSON.parse([...h.storage.backing.values()][0]);assert.equal(marker.segmentId,s.segmentId);assert.equal(marker.status,'sealed');}));
test('lifecycle service pending review cannot change pack access controls',()=>withLifecycleController(async h=>{await h.click('begin');await h.click('pack-observer');assert.equal(h.packConfiguration[C.fixtures.pack].ownership.PLAYER,'NONE');await h.click('finish');const s=await h.controller.exportSegment();assert.equal(s.firstFailure,null);assert.equal(s.mutations.length,0);}));
test('lifecycle pending review cannot contain a fresh-update operation marker',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','pending-fresh')),s=localSegment(issued),c=await capture(plan),beforeActor={synthetic:1},afterActor={synthetic:2};beginEvent(s,c);event(s,'operation',{kind:'fresh-update',oldView:{synthetic:true},oldViewAfter:{synthetic:true},oldCaptureUnchanged:true,beforeActor,afterActor,before:sha(beforeActor),after:sha(afterActor),prepared:{level:2,rank:3}});event(s,'capture',c);await assertLifecycleRejected(issued,s);});

function fabricatedAcceptedHistory(issued,s){const p=copy(issued.plan),segmentBytes=JSON.stringify(s);p.checkpoint={...copy(s.controlState),mutations:copy(s.mutations),operations:s.events.filter(e=>e.kind==='operation').map(e=>copy(e.value)),captures:copy(s.captures),failure:copy(s.firstFailure)};p.handoff.acceptedSegments=[{segmentId:s.segmentId,segmentSha256:sha(segmentBytes),segmentBytes,packetBytes:issued.packetBytes,packetSha256:sha(issued.packetBytes),segment:copy(s),packet:copy(issued.packet)}];p.handoff.revision=1;p.handoff.issued=null;return p;}
async function temporalCounterexample(kind){const chain=await setupChain(),s=copy(chain.segment),c=await capture(chain.plan);s.captures=[c];const before=kind==='before-creation'?0:s.events.findIndex(e=>e.kind==='mutation'&&s.mutations[e.index].kind==='access');assert.ok(before>=0);s.events.splice(before,0,{kind:'operation',value:{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied}},{kind:'capture',index:0});s.events.forEach((e,n)=>e.sequence=n);return {issued:chain.issued,segment:s,forged:fabricatedAcceptedHistory(chain.issued,s)};}
for(const kind of ['before-creation','before-grants']){
    test('causal '+kind+' segment rejects later receipts certifying an earlier review',async()=>{const {issued,segment}=await temporalCounterexample(kind);assert.ok(admittedControllerSegmentErrors(segment,issued.packet).some(e=>e.includes('event-prefix')));});
    test('causal '+kind+' private merge rejects later prerequisite receipts',async()=>{const {issued,segment}=await temporalCounterexample(kind);await assert.rejects(merge(issued.plan,segment),/event-prefix/);});
    test('causal '+kind+' fabricated accepted history fails private replay',async()=>{const {forged}=await temporalCounterexample(kind);assert.deepEqual(errors(forged),[]);const result=await replayAdmittedControllerHistory(forged);assert.equal(result.status,'failed');assert.ok(result.errors.some(e=>e.includes('event-prefix')));});
    test('causal '+kind+' fabricated accepted history cannot bypass validation through an identical retry',async()=>{const {forged,segment}=await temporalCounterexample(kind);await assert.rejects(merge(forged,segment),/event-prefix/);});
}

function reviewEvents(s,c){event(s,'operation',{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'capture',c);}
function mutationFor(p,kind,role,extra={}){return {kind,uuid:p.checkpoint.resources.find(r=>r.role===role).uuid,userId:C.pin.gm,batch:p.batch,...extra};}
async function gmControlSegment(p,mutations,ops,suffix,phase='gm'){const issued=await issue(p,optionsFor(p,C.pin.gm,phase,suffix)),s=localSegment(issued);for(const m of mutations)event(s,'mutation',m);for(const o of ops)event(s,'operation',o);return {issued,segment:s,plan:await merge(issued.plan,s)};}
test('causal review after setup and grants in the same segment remains valid',async()=>{const chain=await setupChain(),s=copy(chain.segment);reviewEvents(s,await capture(chain.plan));assert.deepEqual(admittedControllerSegmentErrors(s,chain.issued.packet),[]);const p=await merge(chain.issued.plan,s);assert.equal(p.checkpoint.captures.length,1);assert.equal((await replayAdmittedControllerHistory(p)).status,'passed');assert.deepEqual(await merge(p,s),p);});
for(const kind of ['setup','grants'])test('causal '+kind+' marker cannot precede the receipts it certifies',async()=>{const chain=await setupChain(),s=copy(chain.segment),n=s.events.findIndex(e=>e.kind==='operation'&&e.value.kind===kind),marker=s.events.splice(n,1)[0],at=kind==='setup'?0:s.events.findIndex(e=>e.kind==='mutation'&&s.mutations[e.index].kind==='access');s.events.splice(at,0,marker);s.events.forEach((e,n)=>e.sequence=n);reviewEvents(s,await capture(chain.plan));assert.ok(admittedControllerSegmentErrors(s,chain.issued.packet).some(e=>e.includes('event-prefix')));await assert.rejects(merge(chain.issued.plan,s),/event-prefix/);assert.equal((await replayAdmittedControllerHistory(fabricatedAcceptedHistory(chain.issued,s))).status,'failed');});
test('causal begin cannot borrow readiness established before a later capture',async()=>{const chain=await setupChain(),s=copy(chain.segment),c=await capture(chain.plan);event(s,'capture',c);s.events.unshift({kind:'operation',value:{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied}});s.events.forEach((e,n)=>e.sequence=n);assert.ok(admittedControllerSegmentErrors(s,chain.issued.packet).some(e=>e.includes('event-prefix')));await assert.rejects(merge(chain.issued.plan,s),/event-prefix/);});
test('causal capture rechecks readiness after a valid begin and before cleanup',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','capture-cleanup')),s=localSegment(issued),c=await capture(plan);event(s,'operation',{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'mutation',mutationFor(plan,'access','target-trainer',{principal:C.pin.player,level:0}));s.controlState.phase='cleanup';event(s,'capture',c);assert.ok(admittedControllerSegmentErrors(s,issued.packet).some(e=>e.includes('event-prefix')));await assert.rejects(merge(issued.plan,s),/event-prefix/);});
test('causal source-parent NONE and Observer handoffs preserve valid denied and readable reviews',async()=>{let {plan}=await setupChain();plan=(await gmControlSegment(plan,[mutationFor(plan,'access','source-parent',{principal:C.pin.player,level:0})],[],'parent-none')).plan;plan=(await captureSegment(plan,'player-denied-source-parent','denied-parent')).plan;plan=(await gmControlSegment(plan,[mutationFor(plan,'access','source-parent',{principal:C.pin.player,level:2})],[],'parent-observer')).plan;plan=(await captureSegment(plan,'player-source-parent-readable','readable-parent')).plan;assert.equal(plan.checkpoint.captures.length,2);assert.equal((await replayAdmittedControllerHistory(plan)).status,'passed');});
test('causal pack NONE Observer NONE handoffs preserve actual retained-reference review controls',async()=>{let {plan}=await setupChain();plan=(await captureSegment(plan,'player-pack-none','pack-none')).plan;plan=(await gmControlSegment(plan,[mutationFor(plan,'pack-configuration','test-pack',{role:'PLAYER',level:'OBSERVER'})],[{kind:'pack-access',level:'OBSERVER'}],'pack-observer')).plan;plan=(await captureSegment(plan,'player-pack-observer','pack-readable')).plan;plan=(await gmControlSegment(plan,[mutationFor(plan,'pack-configuration','test-pack',{role:'PLAYER',level:'NONE'})],[{kind:'pack-access',level:'NONE'}],'pack-revoke')).plan;plan=(await captureSegment(plan,'player-pack-revoked','pack-revoked')).plan;assert.deepEqual(plan.checkpoint.captures.map(c=>c.caseId),['player-pack-none','player-pack-observer','player-pack-revoked']);assert.equal((await replayAdmittedControllerHistory(plan)).status,'passed');});
test('causal pack-access marker cannot use a later configuration mutation',async()=>{const {plan}=await setupChain(),issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','pack-order')),s=localSegment(issued);event(s,'operation',{kind:'pack-access',level:'OBSERVER'});event(s,'mutation',mutationFor(plan,'pack-configuration','test-pack',{role:'PLAYER',level:'OBSERVER'}));assert.ok(admittedControllerSegmentErrors(s,issued.packet).some(e=>e.includes('event-prefix')));await assert.rejects(merge(issued.plan,s),/event-prefix/);});
test('causal full owned cleanup preserves earlier captures and rejects reviews after cleanup',async()=>{let {plan}=await setupChain();plan=(await captureSegment(plan,'gm-trainer-core-to-optional','before-cleanup')).plan;const issued=await issue(plan,optionsFor(plan,C.pin.gm,'gm','owned-cleanup')),s=localSegment(issued);s.controlState.phase='cleanup';for(const role of [...C.access.observerRoles,C.access.limitedRole])event(s,'mutation',mutationFor(plan,'access',role,{principal:C.pin.player,level:0}));event(s,'mutation',mutationFor(plan,'pack-configuration','test-pack',{role:'PLAYER',level:'NONE'}));event(s,'operation',{kind:'pack-access',level:'NONE'});for(const r of plan.checkpoint.resources.filter(r=>r.kind==='packItem'))event(s,'mutation',mutationFor(plan,'delete',r.role));event(s,'mutation',mutationFor(plan,'delete','test-pack'));for(const r of plan.checkpoint.resources.filter(r=>r.kind==='Actor')){event(s,'mutation',mutationFor(plan,'delete',r.role));for(const child of plan.checkpoint.resources.filter(c=>c.parentUuid===r.uuid))event(s,'mutation',mutationFor(plan,'delete-with-parent',child.role));}for(const r of plan.checkpoint.resources.filter(r=>r.kind==='worldItem'))event(s,'mutation',mutationFor(plan,'delete',r.role));event(s,'operation',{kind:'cleanup-before-macro-delete',snapshot:{synthetic:true}});event(s,'mutation',mutationFor(plan,'delete','test-macro'));event(s,'operation',{kind:'macro-deleted'});assert.deepEqual(admittedControllerSegmentErrors(s,issued.packet),[]);const final=await merge(issued.plan,s);assert.deepEqual(final.checkpoint.captures,plan.checkpoint.captures);assert.equal((await replayAdmittedControllerHistory(final)).status,'passed');const next=await issue(final,optionsFor(final,C.pin.gm,'cleanup','post-cleanup')),bad=localSegment(next);reviewEvents(bad,await capture(final,'gm-pokemon-optional-to-core'));await assert.rejects(merge(next.plan,bad),/event-prefix/);});

test('private host serially merges GM/player/reload segments without publishing aggregate captures',async()=>{let {plan}=await setupChain();const gm=await captureSegment(plan,'gm-trainer-core-to-optional','gm');plan=gm.plan;const player=await captureSegment(plan,'player-trainer-review','player');assert.doesNotMatch(player.issued.packetBytes,/gm-trainer-core-to-optional.*summary|beforeSha256|PRIVATE/);assert.equal(player.segment.captures.length,1);assert.equal(player.segment.captures[0].identity.user,C.pin.player);const reload=await captureSegment(player.plan,'player-reload-preservation','reload');assert.equal(reload.plan.handoff.revision,4);assert.equal(reload.plan.checkpoint.captures.length,3);assert.deepEqual(reload.plan.checkpoint.captures.slice(0,2),player.plan.checkpoint.captures);assert.deepEqual(errors(reload.plan),[]);});
test('packet validators reject private plans and nested private fields at every public entry',async()=>{assert.ok(publicAdmittedPacketErrors(observedPlan()).length);const base=await packet(observedPlan());for(const mutate of [p=>p.baseline={},p=>p.resources[0].private={},p=>p.controlReceipts[0].private={},p=>p.runtime[0].private={},p=>p.mappings[0].source.private={},p=>p.audience.private={},p=>p.resume.captures=[],p=>p.baselineChecks.ids=[]]){const p=copy(base);mutate(p);assert.ok(publicAdmittedPacketErrors(p).length);}const p=copy(base);p.resources[0]=null;assert.ok(publicAdmittedPacketErrors(p).length);});
test('serial issue refuses forked or unacknowledged handoffs and native pre-created fixtures',async()=>{const p=activeEmpty(),i=await issue(p,optionsFor(p));assert.deepEqual((await issue(i.plan,optionsFor(p))).plan,i.plan);await assert.rejects(issue(i.plan,optionsFor(p,C.pin.gm,'initial','fork')),/outstanding/);await assert.rejects(issue(observedPlan('native'),optionsFor(observedPlan('native'))),/before fixture/);await assert.rejects(issue(pending(),{}),/held/);});
test('identical accepted bytes are idempotent; reused IDs, stale parent and changed baseline fail',async()=>{const {issued,segment,plan}=await setupChain();assert.deepEqual(await merge(plan,segment),plan);const changed=copy(segment);changed.navigation.timeOrigin++;await assert.rejects(merge(plan,changed),/different bytes/);for(const mutate of [p=>p.baseline.settings[0].value.changed=true,p=>p.checkpoint.phase='cleanup']){const p=copy(issued.plan);mutate(p);await assert.rejects(merge(p,segment),/baseline\/history|stale/);}const s=copy(segment);s.parentRevision++;await assert.rejects(merge(issued.plan,s),/anchor/);await assert.rejects(merge(issued.plan,segment,{segmentBytes:JSON.stringify({...segment,firstFailure:{reason:'substitution'}})}),/semantic/);});
test('local event order, identity and player GM-mutation substitution are rejected',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','p')),s=localSegment(i);for(const mutate of [s=>s.identity.user=C.pin.gm,s=>s.identity.private={},s=>event(s,'mutation',{kind:'access',uuid:s.controlState.resources[0].uuid,userId:C.pin.gm,batch:plan.batch,principal:C.pin.player,level:0}),s=>event(s,'operation',null),s=>s.events.push({sequence:1,kind:'operation',value:{kind:'macro-deleted'}}),s=>s.controlState.resources.reverse()]){const bad=copy(s);mutate(bad);assert.ok(admittedControllerSegmentErrors(bad,i.packet).length);await assert.rejects(merge(i.plan,bad));}});
test('first failure remains private and sticky through acknowledgements and subsequent cleanup',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','failure')),s=localSegment(i);event(s,'operation',{kind:'failure',reason:'PRIVATE-FAILURE-DETAIL'});s.firstFailure={reason:'PRIVATE-FAILURE-DETAIL'};const merged=await merge(i.plan,s),next=await issue(merged,optionsFor(merged,C.pin.gm,'cleanup','cleanup'));assert.equal(next.packet.resume.stopLatched,true);assert.equal(next.packet.resume.firstFailureRef,sha(s.firstFailure));assert.doesNotMatch(next.packetBytes,/PRIVATE-FAILURE-DETAIL/);const clear=copy(s);clear.firstFailure=null;await assert.rejects(merge(i.plan,clear),/failure/);const cleanup=localSegment(next);event(cleanup,'operation',{kind:'failure',reason:'Second failure'});cleanup.firstFailure={reason:'Second failure'};const final=await merge(next.plan,cleanup);assert.deepEqual(final.checkpoint.failure,s.firstFailure);});
test('bootstrap absence requires an out-of-record verifier before any claim/tag',async()=>{const p=activeEmpty('native'),config=await packet(p),uuid=config.baselineChecks.bootstrapMacroUuid,macro={documentName:'Macro',uuid,id:uuid.split('.')[1],author:{id:C.pin.gm},ownership:{default:0,[C.pin.gm]:3},getFlag:()=>undefined};const calls=[];assert.throws(()=>verifyFeatureReviewBootstrap(config,identityFor(C.pin.gm),macro,x=>{calls.push(x.operation);if(x.operation==='verify-private-macro-absence')throw Error('Private baseline absence not verified');}),/absence not verified/);assert.deepEqual(calls,['bootstrap-macro','verify-private-macro-absence']);p.baseline.ids.macros.push(macro.id);p.baseline.protectedDocuments.push({collection:'macros',id:macro.id,data:{_id:macro.id}});await assert.rejects(packet(p),/privately excluded/);});
test('refresh requires private acknowledgement, preserves failures and retains actual document object identity',async()=>{const {plan}=await setupChain('native'),first=await captureSegment(plan,'player-trainer-review','p1'),next=await issue(first.plan,optionsFor(first.plan,C.pin.player,'player','p2'));const retained=[{nativeReference:{marker:'Do not serialize/recreate'}}],exported={segment:first.segment,bytes:JSON.stringify(first.segment),sha256:sha(JSON.stringify(first.segment)),eventCount:first.segment.events.length},args={packet:first.issued.packet,next:next.packet,exported,localEventCount:exported.eventCount,pendingReview:false,identity:identityFor(C.pin.player),verifyExecution:()=>{},packetSha256:sha(next.packetBytes)};const value=await refreshFeatureReviewPacket(args,retained);assert.equal(value.retainedReferences,retained);assert.equal(value.retainedReferences[0],retained[0]);await assert.rejects(refreshFeatureReviewPacket({...args,verifyExecution:()=>{throw Error('Missing private acknowledgement');}},retained),/acknowledgement/);await assert.rejects(refreshFeatureReviewPacket({...args,localEventCount:999},retained),/unexported/);await assert.rejects(refreshFeatureReviewPacket({...args,pendingReview:true},retained),/unfinished/);await assert.rejects(refreshFeatureReviewPacket({...args,next:first.issued.packet},retained),/stale/);});
test('private replay binds all segment bytes and rejects aggregate edits or missing raw segments',()=>temp(async dir=>{let {plan}=await setupChain();plan=(await captureSegment(plan,'gm-trainer-core-to-optional','g')).plan;await rawProofs(dir,plan);for(let n=0;n<plan.handoff.acceptedSegments.length;n++){const a=plan.handoff.acceptedSegments[n],path=`raw/segment-${n}.json`;await fs.writeFile(join(dir,path),a.segmentBytes);plan.evidence.raw.push({kind:'controller-segment',private:true,path,sha256:a.segmentSha256});}let result=await check(plan,{rawDirectory:dir});assert.equal(result.integrity,'passed',result.errors.join('; '));assert.equal(result.controllerReplay,'passed');assert.equal(result.nativeCases.passed,0);const edited=copy(plan);edited.checkpoint.operations.push({kind:'macro-deleted'});assert.equal((await check(edited,{rawDirectory:dir})).controllerReplay,'failed');plan.evidence.raw.pop();assert.equal((await check(plan,{rawDirectory:dir})).integrity,'failed');}));

test('compendium commitment tampering cannot be merged against the privately issued packet',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','configuration'));i.plan.handoff.issued.packet.baselineChecks.packConfigurationSha256='b'.repeat(64);i.plan.handoff.issued.packetBytes=JSON.stringify(i.plan.handoff.issued.packet);i.plan.handoff.issued.packetSha256=sha(i.plan.handoff.issued.packetBytes);const s=localSegment({packet:i.plan.handoff.issued.packet,packetBytes:i.plan.handoff.issued.packetBytes});await assert.rejects(merge(i.plan,s),/differs from latest/);});
test('local failed segments cannot continue cases and player segments cannot invent GM operations',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','stopped')),s=localSegment(i),c=await capture(plan,'player-trainer-review');event(s,'operation',{kind:'failure',reason:'Stop now'});s.firstFailure={reason:'Stop now'};event(s,'operation',{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'capture',c);assert.ok(admittedControllerSegmentErrors(s,i.packet).some(e=>e.includes('stopped')));const bad=localSegment(i);event(bad,'operation',{kind:'macro-deleted'});assert.ok(admittedControllerSegmentErrors(bad,i.packet).some(e=>e.includes('GM operations')));});
test('malformed private handoff structures and non-JSON segment fields fail without proof IO',async()=>{for(const handoff of [null,{},[],{revision:0,issued:null,acceptedSegments:[null],genesisCheckpoint:null}]){const p=observedPlan();p.handoff=handoff;assert.ok(errors(p).length);assert.equal((await check(p)).integrity,'failed');}const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','malformed'));for(const mutate of [s=>s.runtime[0]=null,s=>s.events=[null],s=>s.controlState=null,s=>s.navigation=null,s=>s.identity=null,s=>s.events=[{sequence:0,kind:'operation',value:null}]]){const s=localSegment(i);mutate(s);assert.ok(admittedControllerSegmentErrors(s,i.packet).length);}});
test('actual player controller initializes and exports only local observations with public input',async()=>{const {plan}=await setupChain('native');plan.baseline.protectedDocuments[0].data.name='PRIVATE-DOCUMENT-CANARY';plan.baseline.settings[0].value.canary='PRIVATE-SETTING-CANARY';plan.baseline.users[0].permissions.canary='PRIVATE-USER-CANARY';const gm=await captureSegment(plan,'gm-trainer-core-to-optional','gm-private');gm.plan.checkpoint.captures[0].dom={text:'PRIVATE-GM-CAPTURE-CANARY'};gm.plan.checkpoint.operations.push({kind:'checkpoint',snapshot:{canary:'PRIVATE-GM-OPERATION-CANARY'}});const inputs=await packet(gm.plan,C.pin.player,'player'),source=await fs.readFile(new URL('../tools/foundry-feature-review-check.mjs',import.meta.url),'utf8'),contractUrl=new URL('../tools/feature-review-admitted-contract.mjs',import.meta.url).href,registryUrl=new URL('../src/util/rule-version-registry.js',import.meta.url).href,unusedLauncher='data:text/javascript,export function launchFeatureAcquisitionReview(){throw Error(%22No native case in this double%22)}';const isolatedSource=source.replace("'./feature-review-admitted-contract.mjs'",JSON.stringify(contractUrl)).replace("'/systems/ptu/src/module/apps/feature-acquisition-review-launcher.js'",JSON.stringify(unusedLauncher)).replace("'/systems/ptu/src/util/rule-version-registry.js'",JSON.stringify(registryUrl));const isolated=await import('data:text/javascript;base64,'+Buffer.from(isolatedSource).toString('base64')),names=['game','fetch','Dialog','sessionStorage'],saved=Object.fromEntries(names.map(n=>[n,Object.getOwnPropertyDescriptor(globalThis,n)]));let output='';const html={find:()=>({val:v=>{if(v!==undefined)output=v;},on:()=>{}})};try{Object.defineProperty(globalThis,'sessionStorage',{configurable:true,value:memoryStorage()});Object.defineProperty(globalThis,'game',{configurable:true,value:{world:{id:C.pin.world,title:C.target.title},version:C.pin.core,system:{id:'ptu',version:C.pin.system},user:{id:C.pin.player,isGM:false},users:copy(C.accounts.users),settings:{get:(scope,key)=>key==='worldSchemaVersion'?0.115:key==='worldSystemVersion'?'4.4.3':{}}}});Object.defineProperty(globalThis,'fetch',{configurable:true,value:async url=>({ok:true,arrayBuffer:async()=>Buffer.from((await fs.readFile(new URL('../'+url.replace('/systems/ptu/',''),import.meta.url),'utf8')).replace(/\r\n/g,'\n'))})});Object.defineProperty(globalThis,'Dialog',{configurable:true,value:class{constructor(config){this.config=config;this.element=html;}render(){this.config.render(html);}}});const controller=await isolated.openFeatureReviewCheck({inputs,verifyExecution:()=>{}}),segment=await controller.exportSegment();assert.equal(segment.identity.user,C.pin.player);assert.deepEqual(segment.captures,[]);assert.deepEqual(segment.mutations,[]);assert.equal(segment.events.length,1);assert.equal(segment.events[0].value.kind,'resume');assert.doesNotMatch(output,/PRIVATE-|gm-trainer-core-to-optional|protectedDocuments|baselineIds/);assert.deepEqual(JSON.parse(output),segment);}finally{for(const name of names)if(saved[name])Object.defineProperty(globalThis,name,saved[name]);else delete globalThis[name];}});
